from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tile size for the inner j loop. This controls the working-set size for
# A[i, j], B[i, j], and x[j] and gives the C compiler a fixed-size inner
# loop that is easy to auto-vectorize.
J_TILE = 64


@proc
def kernel_gesummv(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    """
    Compute, for each row i:

        tmp[i] = sum_j A[i, j] * x[j]
        y[i]   = alpha * tmp[i] + beta * sum_j B[i, j] * x[j]

