        # Per-row accumulators kept in registers.
        accA: DATA_TYPE
        accB: DATA_TYPE
        accA = 0.0
        accB = 0.0

        # Fused dot products over row i:
        #   accA = Σ_j A[i,j] * x[j]
        #   accB = Σ_j B[i,j] * x[j]
        for j in seq(0, n):
            accA += A[i, j] * x[j]
            accB += B[i, j] * x[j]

