#    Each iteration i reads A[i, :], B[i, :], x[:] and writes tmp[i], y[i].
#    Different rows are independent, so we can safely parallelize over i.
i_loop = kernel_gesummv.find_loop("i")
kernel_gesummv = parallelize_loop(kernel_gesummv, i_loop)

# 2. Tile (block) the inner reduction loop over j.
#    This transforms:
#        for j in seq(0, n):
#            ...
#    into a pair of loops:
#        for j_outer in seq(0, n / J_TILE):
#            for j_inner in seq(0, J_TILE):
#                j = J_TILE * j_outer + j_inner
#                ...
#        # plus a guarded tail loop for the remainder when n is not
#        # divisible by J_TILE.
